pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 1 ether}(1000);

        address alice = address(0x123);
        vm.prank(alice);
        c.getFreeKilo();

        vm.warp(block.timestamp + c.DRUGS_TO_PRODUCE_1KILO());

        address ref = address(0x456);
        vm.prank(alice);
        c.collectDrugs(ref);

        bool referenceBehavior = (c.claimedDrugs(ref) > 0);
        assertTrue(referenceBehavior);
    }
}
